// Gallery page: one section per film (video · style · prompt · source), in Chinese and English.
// Data: site/data.js (generated by the build script). Both languages sit in the DOM (.zh / .en); <html data-lang> picks one.
(() => {
  const FILMS = window.FILMS || [];
  const $ = (s, el = document) => el.querySelector(s);
  const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const L = (zh, en) => `<span class="zh">${zh}</span><span class="en">${en}</span>`;   // both are HTML
  const kb = (n) => (n >= 1e6 ? (n / 1e6).toFixed(1) + ' MB' : Math.max(1, Math.round(n / 1e3)) + ' KB');
  const pad = (n) => String(n).padStart(2, '0');
  const TITLE = { zh: '15 种 MG 动态设计风格 · 成片、提示词与源码', en: '15 Motion Design Styles · Films, Prompts and Source' };

  // ---------- language ----------
  const setLang = (l, save) => {
    const root = document.documentElement;
    root.dataset.lang = l;
    root.lang = l === 'zh' ? 'zh-CN' : 'en';
    document.title = TITLE[l];
    if (save) try { localStorage.setItem('mg15-lang', l); } catch (e) { /* private mode */ }
  };
  setLang(document.documentElement.dataset.lang === 'zh' ? 'zh' : 'en', false);   // English unless chosen otherwise
  $('#lang').addEventListener('click', () => setLang(document.documentElement.dataset.lang === 'zh' ? 'en' : 'zh', true));

  // Links into the GitHub repo when the page runs on <user>.github.io (or <meta name="repo"> is set); plain paths otherwise.
  const meta = (n) => (document.querySelector(`meta[name="${n}"]`) || {}).content || '';
  const BRANCH = meta('repo-branch').trim() || 'main';
  const REPO = (() => {
    const m = meta('repo').trim();
    if (m) return m.replace(/\/+$/, '');
    const host = location.hostname;
    if (!host.endsWith('.github.io')) return null;
    const seg = location.pathname.split('/').filter(Boolean)[0];
    return `https://github.com/${host.split('.')[0]}/${seg && !seg.includes('.') ? seg : host}`;
  })();
  const blob = (p) => (REPO ? `${REPO}/blob/${BRANCH}/${p}` : p);
  const tree = (p) => (REPO ? `${REPO}/tree/${BRANCH}/${p}` : p);
  document.querySelectorAll('a[data-repo]').forEach((a) => { a.href = blob(a.dataset.repo); });

  const inline = (s) => esc(s)
    .replace(/`([^`]+)`/g, '<code>$1</code>')
    .replace(/\*\*([^*]+)\*\*/g, '<b>$1</b>')
    .replace(/\[([^\]]+)\]\(\.\.\/([^)]+)\)/g, (_, t, p) => `<a href="${esc(blob(p))}">${t}</a>`);
  const promptHTML = (t) => esc(t).split('\n').map((l) => (l.startsWith('# ') ? `<span class="h">${l}</span>` : l)).join('\n');
  const zhName = (f) => esc(f.name.join(' · '));

  // ---------- index + sticky bar ----------
  $('#index').innerHTML = FILMS.map((f) => `<a href="#${f.slug}" style="--c:${f.accent}"><b>${pad(f.n)}</b>${L(`<span>${esc(f.name.join(' '))}</span>`, `<span>${esc(f.name_en)}</span>`)}</a>`).join('');
  $('#bar-nav').innerHTML = FILMS.map((f) => `<a href="#${f.slug}" data-s="${f.slug}" style="--c:${f.accent}">${L(esc(f.name.join(' ')), esc(f.name_en))}</a>`).join('');

  // ---------- sections ----------
  const main = $('#films');
  for (const f of FILMS) {
    const sec = document.createElement('section');
    sec.className = 'film' + (f.portrait ? ' portrait' : '');
    sec.id = f.slug;
    sec.style.setProperty('--accent', f.accent);
    sec.innerHTML = `
      <div class="film-in">
        <div class="head">
          <div class="num">${pad(f.n)} / ${pad(FILMS.length)}</div>
          <div><h2>${L(zhName(f), esc(f.name_en))}</h2><div class="en-sub">${L(esc(f.en), zhName(f))}</div></div>
          <div class="work"><small>${L('原片', 'Film')}</small>${L(esc(f.work), esc(f.work_en))}</div>
        </div>
        <div class="body">
          <div class="player" style="--ar:${f.w}/${f.h}">
            <video controls playsinline preload="none" poster="${esc(f.poster)}" width="${f.w}" height="${f.h}">
              <source src="${esc(f.video)}" type="video/mp4">
            </video>
          </div>
          <div class="about">
            <h4>${L('风格说明', 'The style')}</h4><p>${L(esc(f.about), esc(f.about_en))}</p>
            <h4>${L('这支片怎么做的', 'How this film was made')}</h4><p>${L(esc(f.how), esc(f.how_en))}</p>
          </div>
        </div>
        <div class="tabs">
          <div class="tabbar">
            <button class="tab" aria-expanded="false" data-pane="prompt">${L('提示词', 'Prompt')}</button>
            <button class="tab" aria-expanded="false" data-pane="code">${L('源码', 'Source')}<small>${L(`${f.files.length} 个文件`, `${f.files.length} files`)}</small></button>
            <span class="sp"></span>
            <button class="btn" data-act="copy-prompt">${L('复制提示词', 'Copy prompt')}</button>
            <a class="btn" data-act="link" hidden></a>
          </div>
          <div class="pane" data-pane="prompt" hidden>
            <ol class="steps">${f.steps.map((s, i) => `<li>${L(inline(s), inline(f.steps_en[i]))}</li>`).join('')}</ol>
            <p class="pnote en">The prompt is shown exactly as it was used. Its style notes are in Chinese; the model reads both languages, so it works as is.</p>
            <pre class="prompt">${promptHTML(f.prompt)}</pre>
          </div>
          <div class="pane" data-pane="code" hidden></div>
        </div>
      </div>`;
    main.appendChild(sec);
    wire(sec, f);
  }

  function wire(sec, f) {
    const box = sec.querySelector('.tabs');
    const tabs = sec.querySelectorAll('.tab');
    const link = sec.querySelector('[data-act="link"]');
    const copyBtn = sec.querySelector('[data-act="copy-prompt"]');
    const show = (name) => {                     // name = null collapses
      tabs.forEach((t) => t.setAttribute('aria-expanded', String(t.dataset.pane === name)));
      sec.querySelectorAll('.pane').forEach((p) => { p.hidden = p.dataset.pane !== name; });
      box.classList.toggle('open', !!name);
      link.hidden = !name;
      if (name === 'code') {
        link.href = tree(`demos/${f.slug}`);
        link.innerHTML = REPO ? L('在 GitHub 查看目录', 'Open folder on GitHub') : esc(`demos/${f.slug}/`);
        initCode(sec, f);
      } else if (name === 'prompt') {
        link.href = blob(f.promptFile);
        link.innerHTML = REPO ? L('在 GitHub 查看', 'Open on GitHub') : esc(f.promptFile);
      }
    };
    tabs.forEach((t) => t.addEventListener('click', () => show(t.getAttribute('aria-expanded') === 'true' ? null : t.dataset.pane)));
    copyBtn.addEventListener('click', () => copy(copyBtn, f.prompt));
    sec._show = show;
  }

  function copy(btn, text) {
    const label = btn.innerHTML;
    const ok = () => { btn.innerHTML = L('已复制', 'Copied'); btn.classList.add('ok'); setTimeout(() => { btn.innerHTML = label; btn.classList.remove('ok'); }, 1400); };
    const fallback = () => {
      const ta = document.createElement('textarea');
      ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
      document.body.appendChild(ta); ta.select();
      try { document.execCommand('copy'); ok(); } catch (e) { /* ignore */ }
      ta.remove();
    };
    if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(text).then(ok, fallback);
    else fallback();
  }

  // ---------- source viewer ----------
  const cache = new Map();
  const codes = (xs) => xs.map((x) => `<code>${esc(x)}</code>`).join(' ');
  function initCode(sec, f, open) {
    const pane = sec.querySelector('.pane[data-pane="code"]');
    if (!pane.dataset.ready) {
      pane.dataset.ready = '1';
      const groups = new Map();
      for (const x of f.files) {
        const i = x.p.lastIndexOf('/');
        const d = i < 0 ? '' : x.p.slice(0, i);
        if (!groups.has(d)) groups.set(d, []);
        groups.get(d).push(x);
      }
      const dirs = [...groups.keys()].sort((a, b) => (a === '' ? -1 : b === '' ? 1 : a.localeCompare(b)));
      const treeHTML = dirs.map((d) => (d ? `<div class="dir">${esc(d)}/</div>` : '') + groups.get(d).map((x) =>
        `<button data-p="${esc(x.p)}" class="${d ? 'sub' : ''}" title="${esc(x.p)}"><span>${esc(d ? x.p.slice(d.length + 1) : x.p)}</span><i>${kb(x.size)}</i></button>`).join('')).join('');
      const fontsLink = `<a href="${esc(blob('assets/fonts/README.md'))}">assets/fonts/README.md</a>`;
      const fonts = f.fonts.length ? codes(f.fonts) : L('无', 'none');
      const local = f.localFonts.length ? L(`；另需放在片子目录里的 ${codes(f.localFonts)}`, `; plus ${codes(f.localFonts)} in the film's folder`) : '';
      const run = `<code>python3 demos/${f.slug}/audio.py</code>`, rend = `<code>node harness/render.mjs demos/${f.slug}</code>`;
      pane.innerHTML = `
        <div class="src">
          <div class="tree">${treeHTML}</div>
          <div class="view"><div class="vbar"><span class="p"></span><span class="s"></span>
            <button class="btn" data-act="copy-file">${L('复制', 'Copy')}</button><a class="btn" data-act="raw" target="_blank" rel="noopener">${L('原始文件', 'Raw file')}</a></div>
            <div class="vbody"></div></div>
        </div>
        <div class="deps">
          <div><b>${L('运行', 'Run')}</b>${L(`${run} 生成配乐，${rend} 渲染成片（在仓库根目录）`, `${run} makes the soundtrack, ${rend} renders the film (from the repository root)`)}</div>
          <div><b>${L('字体', 'Fonts')}</b>${fonts}${local}${L(`（不在仓库里，见 ${fontsLink}）`, ` (not in the repository, see ${fontsLink})`)}</div>
          ${f.npm.length ? `<div><b>npm</b>${codes(f.npm)}</div>` : ''}
          ${f.shared.length ? `<div><b>${L('共享素材', 'Shared assets')}</b>${codes(f.shared)}${L('（已包含）', ' (included)')}</div>` : ''}
          <div><b>${L('音频', 'Audio')}</b>${L(`音频工具包 <code>lib/audio</code>（已包含${f.audioSamples ? `，用到 ${f.audioSamples} 个乐器采样` : ''}）`,
            `the audio toolkit <code>lib/audio</code> (included${f.audioSamples ? `; this film uses ${f.audioSamples} instrument samples` : ''})`)}</div>
        </div>`;
      pane.querySelectorAll('.tree button').forEach((b) => b.addEventListener('click', () => openFile(pane, f, b.dataset.p, true)));
      pane.querySelector('[data-act="copy-file"]').addEventListener('click', (e) => { if (pane._text != null) copy(e.currentTarget, pane._text); });
    }
    const first = open || pane._cur || (f.files.find((x) => x.p === 'index.html') || f.files[0]).p;
    openFile(pane, f, first, !!open);
  }

  async function openFile(pane, f, p, setHash) {
    const x = f.files.find((y) => y.p === p);
    if (!x) return;
    pane._cur = p;
    pane._text = null;
    pane.querySelectorAll('.tree button').forEach((b) => b.classList.toggle('cur', b.dataset.p === p));
    const url = `demos/${f.slug}/${p}`;
    $('.vbar .p', pane).textContent = url;
    $('.vbar .s', pane).textContent = kb(x.size);
    $('[data-act="raw"]', pane).href = url;
    $('[data-act="copy-file"]', pane).hidden = x.kind !== 'code';
    const body = $('.vbody', pane);
    body.scrollTop = 0; body.scrollLeft = 0;
    if (setHash) history.replaceState(null, '', `#${f.slug}:${p}`);
    if (x.kind === 'image') { body.innerHTML = `<div class="media"><img src="${esc(url)}" alt="${esc(p)}"></div>`; return; }
    if (x.kind === 'audio') { body.innerHTML = `<div class="media"><audio controls preload="none" src="${esc(url)}"></audio></div>`; return; }
    const big = x.size > 400e3 || (x.p.endsWith('.json') && x.size > 120e3);
    if (x.kind !== 'code' || big) {
      body.innerHTML = `<div class="note">${big
        ? L(`数据文件较大（${kb(x.size)}），不在页面里显示。点右上角「原始文件」下载查看。`, `Large data file (${kb(x.size)}), not shown here. Use "Raw file" to download it.`)
        : L(`二进制文件（${kb(x.size)}），不在页面里显示。点右上角「原始文件」下载查看。`, `Binary file (${kb(x.size)}), not shown here. Use "Raw file" to download it.`)}</div>`;
      return;
    }
    body.innerHTML = `<div class="note">${L('读取中…', 'Loading…')}</div>`;
    let text;
    try {
      if (!cache.has(url)) cache.set(url, fetch(url).then((r) => { if (!r.ok) throw new Error(r.status); return r.text(); }));
      text = await cache.get(url);
    } catch (e) {
      cache.delete(url);
      const local = location.protocol === 'file:';
      body.innerHTML = `<div class="note">${L(`读不到这个文件。${local ? '直接双击打开的页面不能读取本地文件，请在仓库根目录运行 <code>python3 -m http.server</code>，再打开 <code>http://localhost:8000</code>。' : ''}`,
        `Could not read this file.${local ? ' A page opened straight from disk cannot read local files: run <code>python3 -m http.server</code> in the repository root and open <code>http://localhost:8000</code>.' : ''}`)}</div>`;
      return;
    }
    if (pane._cur !== p) return;
    pane._text = text;
    const n = text.split('\n').length;
    let html = esc(text);
    if (window.hljs && x.lang && x.lang !== 'plaintext' && text.length < 300e3) {
      try { html = window.hljs.highlight(text, { language: x.lang, ignoreIllegals: true }).value; } catch (e) { /* plain */ }
    }
    let gut = '';
    for (let i = 1; i <= n; i++) gut += i + '\n';
    body.innerHTML = `<div class="code"><pre class="gut">${gut}</pre><pre><code class="hljs">${html}</code></pre></div>`;
  }

  // ---------- one video at a time ----------
  document.addEventListener('play', (e) => {
    document.querySelectorAll('video').forEach((v) => { if (v !== e.target && !v.paused) v.pause(); });
  }, true);

  // ---------- sticky bar + current section ----------
  const bar = $('#bar');
  new IntersectionObserver(([en]) => bar.classList.toggle('on', !en.isIntersecting), { rootMargin: '-120px 0px 0px 0px' }).observe($('#index'));
  const navLinks = new Map([...document.querySelectorAll('#bar-nav a')].map((a) => [a.dataset.s, a]));
  const secObs = new IntersectionObserver((ens) => {
    for (const en of ens) {
      if (!en.isIntersecting) continue;
      navLinks.forEach((a, s) => a.classList.toggle('cur', s === en.target.id));
      const a = navLinks.get(en.target.id);
      if (a) a.scrollIntoView({ block: 'nearest', inline: 'center' });
    }
  }, { rootMargin: '-45% 0px -50% 0px' });
  document.querySelectorAll('.film').forEach((s) => secObs.observe(s));

  // ---------- deep links: #slug  or  #slug:path/in/demo ----------
  const fromHash = () => {
    const h = decodeURIComponent(location.hash.slice(1));
    if (!h) return;
    const [slug, ...rest] = h.split(':');
    const sec = document.getElementById(slug);
    const f = FILMS.find((x) => x.slug === slug);
    if (!sec || !f) return;
    if (rest.length) { sec._show('code'); initCode(sec, f, rest.join(':')); }
    sec.scrollIntoView();
  };
  window.addEventListener('hashchange', fromHash);
  fromHash();
})();
